// variant of https://shadertoy.com/view/4dGSWR

#define T(U)     texelFetch(iChannel0, ivec2(U+R)/4%ivec2(R/4.), 2)
#define hue(v)  ( .6 + .6 * cos( 6.3*(v)  + vec4(0,23,21,0)  ) )

void mainImage( out vec4 O, vec2 u ){
    O = fract(iTime/2.) < .5
      ? textureLod(iChannel0, P(u)/R, 2.).xxxx  // interpolated
      : T(P(u)).xxxx;                           // not interpolated

    if (fract(O.x)>0.) O *= 4.*hue(2.*O.x);     // coloring scheme


}

#define T +texture(iChannel0, P+=

void mainImage( out vec4 O, vec2 U )
{
    vec2 M = P(iMouse.xy),
         h=1./R, v=h, P=U*h; h.y = v.x = 0.,

    O =  T-v) T+h) T+v) T+v)  T-h)  T-h) T-v) T-v) - 3.;     // count life in neighborhood

    O = vec4(   O*O==-T+h+v)*O                               // 2 neighbors:survive 3:birth
              ||   iFrame < 1  && fract(1e4*sin(dot(U,71.-R))) > .3  // initial state
